public without sharing class ContactTriggerHandler {
    private static Map<Id, Account> accountMap = new Map<Id, Account>();
    private static Set<Id> processedAccountIds = new Set<Id>();

    public static void handleBefore(List<Contact> contacts, Boolean isInsert) {
        Set<Id> accountIds = new Set<Id>();

        for (Contact c : contacts) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        loadAccounts(accountIds);

        for (Contact c : contacts) {
            if (c.AccountId == null) {
                continue;
            }

            Account a = accountMap.get(c.AccountId);
            if (a == null) {
                continue;
            }

            if (String.isBlank(c.MailingCountry)) {
                c.MailingCountry = a.BillingCountry;
            }

            if (isInsert && String.isBlank(c.LeadSource)) {
                c.LeadSource = a.AccountSource;
            }
        }
    }

    public static void handleAfterInsert(List<Contact> contacts) {
        List<Account> accountsToUpdate = new List<Account>();

        for (Contact c : contacts) {
            if (c.AccountId == null || String.isBlank(c.Phone)) {
                continue;
            }

            if (processedAccountIds.contains(c.AccountId)) {
                continue;
            }

            processedAccountIds.add(c.AccountId);

            Account a = accountMap.get(c.AccountId);
            if (a != null && String.isBlank(a.Phone)) {
                a.Phone = c.Phone;
                accountsToUpdate.add(a);
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }

    private static void loadAccounts(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        Set<Id> missingIds = new Set<Id>();
        for (Id accountId : accountIds) {
            if (!accountMap.containsKey(accountId)) {
                missingIds.add(accountId);
            }
        }

        if (missingIds.isEmpty()) {
            return;
        }

        accountMap.putAll([
            SELECT Id, BillingCountry, AccountSource, Phone
            FROM Account
            WHERE Id IN :missingIds
        ]);
    }
}
