public with sharing class ContactLookupAction {

    public class Request {
        @InvocableVariable(label='Email' required=true)
        public String email;
    }

    public class Result {
        @InvocableVariable(label='Contact ID')
        public Id contactId;

        @InvocableVariable(label='Found')
        public Boolean found;
    }

    @InvocableMethod(label='Find Contact by Email' description='Finds an existing contact by email address.')
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();

        if (requests == null) {
            return results;
        }

        // Pre-populate one result per request, in order.
        for (Integer i = 0; i < requests.size(); i++) {
            Result result = new Result();
            result.found = false;
            result.contactId = null;
            results.add(result);
        }

        Set<String> emailsToQuery = new Set<String>();
        Map<String, List<Integer>> emailToRequestIndexes = new Map<String, List<Integer>>();

        for (Integer i = 0; i < requests.size(); i++) {
            Request request = requests[i];

            if (request == null || String.isBlank(request.email)) {
                continue;
            }

            String normalizedEmail = request.email.trim().toLowerCase();

            emailsToQuery.add(normalizedEmail);

            if (!emailToRequestIndexes.containsKey(normalizedEmail)) {
                emailToRequestIndexes.put(normalizedEmail, new List<Integer>());
            }

            emailToRequestIndexes.get(normalizedEmail).add(i);
        }

        if (emailsToQuery.isEmpty()) {
            return results;
        }

        // Single SOQL query for the whole batch. Respects sharing since the class is with sharing.
        List<Contact> contacts = [
            SELECT Id, Email, CreatedDate
            FROM Contact
            WHERE Email IN :emailsToQuery
            ORDER BY CreatedDate ASC, Id ASC
        ];

        Set<String> assignedEmails = new Set<String>();

        for (Contact contact : contacts) {
            if (String.isBlank(contact.Email)) {
                continue;
            }

            String normalizedContactEmail = contact.Email.trim().toLowerCase();

            if (!emailToRequestIndexes.containsKey(normalizedContactEmail)) {
                continue;
            }

            if (assignedEmails.contains(normalizedContactEmail)) {
                continue;
            }

            assignedEmails.add(normalizedContactEmail);

            for (Integer requestIndex : emailToRequestIndexes.get(normalizedContactEmail)) {
                results[requestIndex].found = true;
                results[requestIndex].contactId = contact.Id;
            }
        }

        return results;
    }
}
