public class PicklistService {

    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }
    }

    public class PicklistServiceException extends Exception {}

    public static List<PicklistService.Option> activeOptions(String objectApiName, String fieldApiName) {
        try {
            validateRequired(objectApiName, fieldApiName);

            String objectName = objectApiName.trim();
            String fieldName = fieldApiName.trim();

            Schema.SObjectType objectType = findObjectType(objectName);
            if (objectType == null) {
                throw new PicklistServiceException('Object not found: ' + objectName);
            }

            Schema.DescribeSObjectResult objectDescribe = objectType.getDescribe();
            Schema.SObjectField field = findField(objectDescribe, fieldName);
            if (field == null) {
                throw new PicklistServiceException('Field not found: ' + fieldName + ' on object ' + objectName);
            }

            Schema.DescribeFieldResult fieldDescribe = field.getDescribe();
            String typeName = fieldDescribe.getType().name();
            if (!typeName.equalsIgnoreCase('PICKLIST') && !typeName.equalsIgnoreCase('MULTIPICKLIST')) {
                throw new PicklistServiceException('Field is not a picklist or multi-select picklist: ' + fieldName);
            }

            Set<String> defaultValues = getDefaultValues(fieldDescribe);
            List<PicklistService.Option> options = new List<PicklistService.Option>();

            List<Schema.PicklistEntry> picklistValues = fieldDescribe.getPicklistValues();
            if (picklistValues != null) {
                for (Schema.PicklistEntry entry : picklistValues) {
                    if (!entry.isActive()) {
                        continue;
                    }

                    Boolean isDefault = entry.isDefaultValue() || defaultValues.contains(entry.getValue());
                    options.add(new Option(entry.getValue(), entry.getLabel(), isDefault));
                }
            }

            return options;
        } catch (PicklistServiceException e) {
            throw e;
        } catch (Exception e) {
            throw new PicklistServiceException('Unexpected error retrieving picklist options: ' + e.getMessage());
        }
    }

    private static void validateRequired(String objectApiName, String fieldApiName) {
        if (String.isBlank(objectApiName)) {
            throw new PicklistServiceException('Object API name is required.');
        }
        if (String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Field API name is required.');
        }
    }

    private static Schema.SObjectType findObjectType(String objectName) {
        String lowerObjectName = objectName.toLowerCase();
        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();

        for (String key : globalDescribe.keySet()) {
            if (key.toLowerCase().equals(lowerObjectName)) {
                return globalDescribe.get(key);
            }
        }

        return null;
    }

    private static Schema.SObjectField findField(Schema.DescribeSObjectResult objectDescribe, String fieldName) {
        String lowerFieldName = fieldName.toLowerCase();
        Map<String, Schema.SObjectField> fields = objectDescribe.fields.getMap();

        for (String key : fields.keySet()) {
            if (key.toLowerCase().equals(lowerFieldName)) {
                return fields.get(key);
            }
        }

        return null;
    }

    private static Set<String> getDefaultValues(Schema.DescribeFieldResult fieldDescribe) {
        Set<String> defaults = new Set<String>();
        Object defaultValue = fieldDescribe.getDefaultValue();

        if (defaultValue != null) {
            String defaultString = String.valueOf(defaultValue);

            if (String.isNotBlank(defaultString)) {
                for (String part : defaultString.split(';')) {
                    String trimmed = part.trim();
                    if (String.isNotBlank(trimmed)) {
                        defaults.add(trimmed);
                    }
                }
            }
        }

        return defaults;
    }
}
