public with sharing class ErpSyncFinalizer implements Finalizer {
    private final Set<Id> accountIds;
    private final Integer attempt;

    public ErpSyncFinalizer(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds == null ? new Set<Id>() : new Set<Id>(accountIds);
        this.attempt = attempt == null ? 1 : attempt;
    }

    public void execute(FinalizerContext context) {
        Boolean isSuccess = context.getResult() == ParentJobResult.SUCCESS;

        FB_Job_Log__c log = new FB_Job_Log__c();
        log.Job_Name__c = 'ErpAccountSyncJob';
        log.Attempt__c = this.attempt;

        if (isSuccess) {
            log.Status__c = 'Success';
        } else {
            log.Status__c = 'Failed';

            Exception ex = context.getException();
            String message = ex == null ? null : ex.getMessage();
            if (message != null && message.length() > 255) {
                message = message.substring(0, 255);
            }
            log.Error__c = message;
        }

        insert log;

        if (!isSuccess && this.attempt != null && this.attempt < 3) {
            System.enqueueJob(new ErpAccountSyncJob(accountIds, this.attempt + 1));
        }
    }
}
