public class LogPurgeJob implements Schedulable, Database.Batchable<sObject> {
    private static final String JOB_NAME = 'Log purge (nightly)';
    private static final String DAILY_CRON = '0 0 2 * * ?';
    private static final Integer BATCH_SIZE = 200;

    public LogPurgeJob() {}

    public void execute(SchedulableContext ctx) {
        Database.executeBatch(this, BATCH_SIZE);
    }

    public Database.QueryLocator start(Database.BatchableContext ctx) {
        Datetime now = Datetime.now();
        Datetime nonErrorCutoff = now.addDays(-30);
        Datetime errorCutoff = now.addDays(-180);

        return Database.getQueryLocator([
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE (CreatedDate < :nonErrorCutoff AND (Level__c != 'ERROR' OR Level__c = null))
               OR CreatedDate < :errorCutoff
        ]);
    }

    public void execute(Database.BatchableContext ctx, List<sObject> scope) {
        if (scope != null && !scope.isEmpty()) {
            Database.delete(scope, false);
        }
    }

    public void finish(Database.BatchableContext ctx) {}

    public static Id scheduleNightly() {
        return System.schedule(JOB_NAME, DAILY_CRON, new LogPurgeJob());
    }
}
