public with sharing class ContactEmailMatcher {

    public class Request {
        @InvocableVariable(required=true)
        public String email;
    }

    public class Result {
        @InvocableVariable
        public Id contactId;
    }

    @InvocableMethod(label='Match Contact by Email')
    public static List<Result> match(List<Request> requests) {
        List<Result> results = new List<Result>();

        if (requests == null || requests.isEmpty()) {
            return results;
        }

        Set<String> normalizedEmails = new Set<String>();
        for (Request request : requests) {
            String normalizedEmail = normalize(request.email);
            if (String.isNotBlank(normalizedEmail)) {
                normalizedEmails.add(normalizedEmail);
            }
        }

        Map<String, Id> earliestContactIdByEmail = new Map<String, Id>();
        if (!normalizedEmails.isEmpty()) {
            List<Contact> contacts = [
                SELECT Id, Email, CreatedDate
                FROM Contact
                WHERE Email IN :normalizedEmails
                ORDER BY CreatedDate ASC, Id ASC
            ];

            for (Contact contact : contacts) {
                String normalizedContactEmail = normalize(contact.Email);
                if (String.isNotBlank(normalizedContactEmail)
                    && normalizedEmails.contains(normalizedContactEmail)
                    && !earliestContactIdByEmail.containsKey(normalizedContactEmail)) {
                    earliestContactIdByEmail.put(normalizedContactEmail, contact.Id);
                }
            }
        }

        for (Request request : requests) {
            Result result = new Result();
            String normalizedEmail = normalize(request.email);
            if (String.isNotBlank(normalizedEmail)) {
                result.contactId = earliestContactIdByEmail.get(normalizedEmail);
            }
            results.add(result);
        }

        return results;
    }

    private static String normalize(String email) {
        if (String.isBlank(email)) {
            return null;
        }
        return email.trim().toLowerCase();
    }
}
