public with sharing class ContactPhoneCleanup {
    /**
     * Normalizes Contact.Phone values by keeping only digits and '+'.
     * Contacts with a null or blank Phone are left out.
     */
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> failures = new Map<Id, String>();

        if (contactIds == null || contactIds.isEmpty()) {
            return failures;
        }

        List<Contact> contacts = [
            SELECT Id, Phone
            FROM Contact
            WHERE Id IN :contactIds AND Phone != null
        ];

        List<Contact> contactsToUpdate = new List<Contact>();
        for (Contact c : contacts) {
            if (String.isBlank(c.Phone)) {
                continue;
            }

            c.Phone = c.Phone.replaceAll('[^0-9+]', '');
            contactsToUpdate.add(c);
        }

        if (contactsToUpdate.isEmpty()) {
            return failures;
        }

        List<Database.SaveResult> saveResults = Database.update(contactsToUpdate, false);

        for (Integer i = 0; i < saveResults.size(); i++) {
            Database.SaveResult result = saveResults[i];
            if (!result.isSuccess() && !result.getErrors().isEmpty()) {
                failures.put(contactsToUpdate[i].Id, result.getErrors()[0].getMessage());
            }
        }

        return failures;
    }
}
