public class DealEventPublisher {
    private static final Integer EVENT_PUBLISH_CHUNK_SIZE = 150;

    public static List<Database.SaveResult> publishStageChanges(List<Opportunity> opportunities) {
        List<Database.SaveResult> results = new List<Database.SaveResult>();

        if (opportunities == null || opportunities.isEmpty()) {
            return results;
        }

        List<Deal_Stage_Change__e> chunk = new List<Deal_Stage_Change__e>();

        for (Opportunity opp : opportunities) {
            if (opp == null) {
                throw new IllegalArgumentException('Opportunities list cannot contain null entries.');
            }

            chunk.add(new Deal_Stage_Change__e(
                Opportunity_Id__c = String.valueOf(opp.Id),
                Stage__c = opp.StageName,
                Amount__c = opp.Amount
            ));

            if (chunk.size() == EVENT_PUBLISH_CHUNK_SIZE) {
                results.addAll(EventBus.publish(chunk));
                chunk = new List<Deal_Stage_Change__e>();
            }
        }

        if (!chunk.isEmpty()) {
            results.addAll(EventBus.publish(chunk));
        }

        return results;
    }
}
