public with sharing class LineItemDiscountHandler {
    /**
     * Bulk-safe discount application for new OpportunityLineItem records.
     *
     * Why this is not a per-line call to PricingRules.standardDiscountFor():
     * - That method issues one SOQL query per product. A 200-line CPQ quote
     *   could exceed governor limits.
     * - OpportunityLineItem.Product2Id can be null in before insert, so we
     *   resolve product ids from PricebookEntryId when necessary.
     * Discount rules remain in PricingRules via standardDiscountForFamily().
     */
    public static void applyStandardDiscount(List<OpportunityLineItem> lines) {
        if (lines == null || lines.isEmpty()) {
            return;
        }

        Set<Id> productIds = new Set<Id>();
        Set<Id> pricebookEntryIds = new Set<Id>();

        for (OpportunityLineItem line : lines) {
            if (line.Discount != null) {
                continue;
            }

            if (line.Product2Id != null) {
                productIds.add(line.Product2Id);
            } else if (line.PricebookEntryId != null) {
                pricebookEntryIds.add(line.PricebookEntryId);
            }
        }

        if (productIds.isEmpty() && pricebookEntryIds.isEmpty()) {
            return;
        }

        Map<Id, PricebookEntry> pricebookEntriesById = new Map<Id, PricebookEntry>();
        if (!pricebookEntryIds.isEmpty()) {
            pricebookEntriesById = new Map<Id, PricebookEntry>([
                SELECT Id, Product2Id
                FROM PricebookEntry
                WHERE Id IN :pricebookEntryIds
            ]);

            for (PricebookEntry entry : pricebookEntriesById.values()) {
                if (entry.Product2Id != null) {
                    productIds.add(entry.Product2Id);
                }
            }
        }

        if (productIds.isEmpty()) {
            return;
        }

        Map<Id, Product2> productsById = new Map<Id, Product2>([
            SELECT Id, Family
            FROM Product2
            WHERE Id IN :productIds
        ]);

        for (OpportunityLineItem line : lines) {
            if (line.Discount != null) {
                continue;
            }

            Id productId = line.Product2Id;
            if (productId == null && line.PricebookEntryId != null) {
                PricebookEntry entry = pricebookEntriesById.get(line.PricebookEntryId);
                if (entry != null) {
                    productId = entry.Product2Id;
                }
            }

            if (productId == null) {
                continue;
            }

            Product2 product = productsById.get(productId);
            if (product != null) {
                line.Discount = PricingRules.standardDiscountForFamily(product.Family);
            }
        }
    }
}
```

