public class CaseSurveyJob implements Queueable {
    private Id caseId;
    private List<Id> caseIds;
    private Boolean isDispatcher;

    /**
     * Worker constructor: processes a single case.
     */
    public CaseSurveyJob(Id caseId) {
        this.caseId = caseId;
        this.isDispatcher = false;
    }

    /**
     * Dispatcher constructor: enqueues one worker per case.
     */
    private CaseSurveyJob(List<Id> caseIds) {
        this.caseIds = caseIds;
        this.isDispatcher = true;
    }

    /**
     * Enqueues one worker Queueable per case, respecting the per-transaction
     * System.enqueueJob limit by chunking and chaining a follow-up dispatcher.
     */
    public static void enqueueCaseIds(List<Id> caseIdsToProcess) {
        if (caseIdsToProcess == null || caseIdsToProcess.isEmpty()) {
            return;
        }

        Integer availableSlots = Limits.getLimitQueueableJobs() - Limits.getQueueableJobs();

        if (availableSlots <= 0) {
            throw new QueueableLimitException('No Queueable jobs can be enqueued in this transaction.');
        }

        Boolean needsFollowUp = caseIdsToProcess.size() > availableSlots;
        Integer workerCount = Math.min(caseIdsToProcess.size(), availableSlots);

        if (needsFollowUp) {
            // Reserve one queueable slot for the follow-up dispatcher.
            workerCount = Math.min(workerCount, availableSlots - 1);
        }

        if (workerCount < 0) {
            workerCount = 0;
        }

        for (Integer i = 0; i < workerCount; i++) {
            System.enqueueJob(new CaseSurveyJob(caseIdsToProcess[i]));
        }

        if (needsFollowUp) {
            List<Id> remainingIds = new List<Id>();

            for (Integer i = workerCount; i < caseIdsToProcess.size(); i++) {
                remainingIds.add(caseIdsToProcess[i]);
            }

            System.enqueueJob(new CaseSurveyJob(remainingIds));
        }
    }

    public void execute(QueueableContext context) {
        if (isDispatcher) {
            enqueueCaseIds(caseIds);
        } else {
            createSurveyTask(caseId);
        }
    }

    private void createSurveyTask(Id caseId) {
        List<Case> matchingCases = [
            SELECT Id, CaseNumber, ContactId
            FROM Case
            WHERE Id = :caseId
            LIMIT 1
        ];

        if (matchingCases.isEmpty()) {
            return;
        }

        Case currentCase = matchingCases[0];

        if (currentCase.ContactId == null) {
            return;
        }

        insert new Task(
            WhatId = currentCase.Id,
            WhoId = currentCase.ContactId,
            Subject = 'CSAT survey: ' + currentCase.CaseNumber,
            ActivityDate = Date.today().addDays(2),
            Status = 'Not Started'
        );
    }

    public class QueueableLimitException extends Exception {}
}
