/**
 * Sends renewal reminders to Opportunity owners.
 *
 * Note: Messaging.SingleEmailMessage.setTargetObjectId() only accepts a User, Lead, or Contact ID.
 * In rare cases Opportunity.OwnerId may point to a queue; that send will fail and is caught below so
 * one bad owner does not prevent the remaining reminders from being sent.
 */
public class RenewalReminderService {
    public static Integer sendReminders(List<Id> opportunityIds) {
        Integer sentCount = 0;

        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return sentCount;
        }

        List<Opportunity> opportunities = [
            SELECT Id, Name, CloseDate, OwnerId
            FROM Opportunity
            WHERE Id IN :opportunityIds
        ];

        for (Opportunity opp : opportunities) {
            try {
                Messaging.SingleEmailMessage email = new Messaging.SingleEmailMessage();
                email.setTargetObjectId(opp.OwnerId);
                email.setSaveAsActivity(false);
                email.setSubject('Renewal due: ' + opp.Name);
                email.setPlainTextBody(
                    'The opportunity ' + opp.Name + ' has a renewal due on ' + opp.CloseDate.format() + '.'
                );

                Messaging.SendEmailResult[] results = Messaging.sendEmail(new Messaging.Email[] { email });

                if (!results.isEmpty() && results[0].isSuccess()) {
                    sentCount++;
                }
            } catch (Exception e) {
                System.debug(
                    LoggingLevel.ERROR,
                    'RenewalReminderService.sendReminders: Failed to send reminder for opportunity ' +
                    opp.Id + ': ' + e.getMessage()
                );
            }
        }

        return sentCount;
    }
}
