public without sharing class AccountCountrySync {
    public static void syncContacts(Map<Id, Account> oldAccountMap, List<Account> newAccounts) {
        if (newAccounts == null || newAccounts.isEmpty() || oldAccountMap == null) {
            return;
        }

        Set<Id> changedAccountIds = new Set<Id>();
        for (Account newAccount : newAccounts) {
            Account oldAccount = oldAccountMap.get(newAccount.Id);
            if (oldAccount != null && newAccount.BillingCountry != oldAccount.BillingCountry) {
                changedAccountIds.add(newAccount.Id);
            }
        }

        if (changedAccountIds.isEmpty()) {
            return;
        }

        Map<Id, List<Contact>> contactsByAccountId = new Map<Id, List<Contact>>();
        for (Contact contact : [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :changedAccountIds
        ]) {
            List<Contact> accountContacts = contactsByAccountId.get(contact.AccountId);
            if (accountContacts == null) {
                accountContacts = new List<Contact>();
                contactsByAccountId.put(contact.AccountId, accountContacts);
            }
            accountContacts.add(contact);
        }

        List<Contact> contactsToUpdate = new List<Contact>();
        for (Account newAccount : newAccounts) {
            Account oldAccount = oldAccountMap.get(newAccount.Id);
            if (oldAccount == null || newAccount.BillingCountry == oldAccount.BillingCountry) {
                continue;
            }

            List<Contact> accountContacts = contactsByAccountId.get(newAccount.Id);
            if (accountContacts == null) {
                continue;
            }

            for (Contact contact : accountContacts) {
                Boolean shouldSync = String.isBlank(contact.MailingCountry)
                    || contact.MailingCountry == oldAccount.BillingCountry;

                if (shouldSync && contact.MailingCountry != newAccount.BillingCountry) {
                    contact.MailingCountry = newAccount.BillingCountry;
                    contactsToUpdate.add(contact);
                }
            }
        }

        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
