import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

const DEBOUNCE_DELAY = 300;
const MIN_SEARCH_LENGTH = 2;

export default class ContactSearch extends LightningElement {
    searchTerm = '';
    contacts = [];
    error;
    _debounceTimer;
    _requestId = 0;
    _isDestroyed = false;

    connectedCallback() {
        this._isDestroyed = false;
    }

    disconnectedCallback() {
        this._isDestroyed = true;
        clearTimeout(this._debounceTimer);
        this._debounceTimer = null;
        this._requestId += 1;
    }

    get hasResults() {
        return this.contacts.length > 0;
    }

    handleChange(event) {
        const rawValue = event.detail && event.detail.value !== undefined
            ? event.detail.value
            : event.target.value;
        const searchTerm = String(rawValue || '');
        const trimmed = searchTerm.trim();

        this.searchTerm = searchTerm;
        this.error = undefined;

        clearTimeout(this._debounceTimer);
        this._debounceTimer = null;

        if (trimmed.length < MIN_SEARCH_LENGTH) {
            this.contacts = [];
            this._requestId += 1;
            return;
        }

        this._debounceTimer = setTimeout(() => {
            this._debounceTimer = null;
            if (this._isDestroyed) {
                return;
            }
            this._search(trimmed);
        }, DEBOUNCE_DELAY);
    }

    _search(searchTerm) {
        const requestId = ++this._requestId;

        searchContacts({ searchTerm })
            .then((result) => {
                if (this._isDestroyed || requestId !== this._requestId) {
                    return;
                }
                this.contacts = result || [];
                this.error = undefined;
            })
            .catch((error) => {
                if (this._isDestroyed || requestId !== this._requestId) {
                    return;
                }
                this.contacts = [];
                this.error = error && error.body && error.body.message
                    ? error.body.message
                    : 'An error occurred';
            });
    }
}
