import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const POLL_INTERVAL_MS = 60000;

export default class QueueMonitor extends LightningElement {
    waiting;
    longestWaitMinutes;
    hasStats = false;
    errorMessage;

    _pollInterval = null;
    _isLoading = false;
    _isConnected = false;

    connectedCallback() {
        this._isConnected = true;
        document.addEventListener('visibilitychange', this.handleVisibilityChange);

        if (document.visibilityState !== 'hidden') {
            this.startPolling();
        }
    }

    disconnectedCallback() {
        this._isConnected = false;
        this.stopPolling();
        document.removeEventListener('visibilitychange', this.handleVisibilityChange);
    }

    handleVisibilityChange = () => {
        if (document.visibilityState === 'hidden') {
            this.stopPolling();
        } else {
            this.startPolling();
        }
    };

    startPolling() {
        this.stopPolling();

        if (document.visibilityState === 'hidden') {
            return;
        }

        this.loadStats();

        this._pollInterval = setInterval(() => {
            this.loadStats();
        }, POLL_INTERVAL_MS);
    }

    stopPolling() {
        if (this._pollInterval !== null) {
            clearInterval(this._pollInterval);
            this._pollInterval = null;
        }
    }

    loadStats() {
        if (this._isLoading || document.visibilityState === 'hidden') {
            return;
        }

        this._isLoading = true;

        getQueueStats()
            .then((result) => {
                if (!this._isConnected) {
                    return;
                }

                this.waiting = result.waiting;
                this.longestWaitMinutes = result.longestWaitMinutes;
                this.hasStats = true;
                this.errorMessage = null;
            })
            .catch((error) => {
                if (!this._isConnected) {
                    return;
                }

                this.errorMessage =
                    error && error.body && error.body.message
                        ? error.body.message
                        : 'An unknown error occurred.';
            })
            .finally(() => {
                this._isLoading = false;
            });
    }
}
