import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    @api heading;

    _tasks = [];
    items = [];
    newLabel = '';
    nextId = 1;

    @api
    get tasks() {
        return this._tasks;
    }
    set tasks(value) {
        this._tasks = Array.isArray(value) ? value : [];
        this.items = this._tasks.map((task) => ({ ...task }));
    }

    get displayHeading() {
        return (this.heading || '').toUpperCase();
    }

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        this.newLabel = event.detail.value;
    }

    handleAdd() {
        const label = (this.newLabel || '').trim();

        if (!label) {
            return;
        }

        const task = {
            id: this.generateTaskId(),
            label,
            done: false
        };

        this.items = [...this.items, task];
        this.newLabel = '';

        this.dispatchEvent(
            new CustomEvent('taskadded', {
                detail: { label },
                bubbles: true,
                composed: true
            })
        );
    }

    handleToggle(event) {
        const taskId = event.target.dataset.id;

        if (!taskId) {
            return;
        }

        this.items = this.items.map((task) =>
            String(task.id) === taskId
                ? { ...task, done: !task.done }
                : task
        );
    }

    generateTaskId() {
        let id;

        do {
            id = `new-${this.nextId++}`;
        } while (this.items.some((task) => String(task.id) === id));

        return id;
    }
}
