public with sharing class EmployerService {
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        Set<Id> contactIds = new Set<Id>();
        Set<Id> organizationIds = new Set<Id>();

        for (Id contactId : employerByContactId.keySet()) {
            if (contactId == null) {
                continue;
            }

            Id organizationId = employerByContactId.get(contactId);
            if (organizationId == null) {
                continue;
            }

            contactIds.add(contactId);
            organizationIds.add(organizationId);
        }

        if (contactIds.isEmpty()) {
            return;
        }

        List<npe5__Affiliation__c> existingAffiliations = [
            SELECT Id, npe5__Contact__c, npe5__Organization__c,
                   npe5__Primary__c, npe5__Status__c, npe5__EndDate__c
            FROM npe5__Affiliation__c
            WHERE npe5__Contact__c IN :contactIds
              AND npe5__Organization__c IN :organizationIds
        ];

        Map<String, npe5__Affiliation__c> existingByContactAndOrg =
            new Map<String, npe5__Affiliation__c>();

        for (npe5__Affiliation__c aff : existingAffiliations) {
            if (aff.npe5__Contact__c == null || aff.npe5__Organization__c == null) {
                continue;
            }

            existingByContactAndOrg.put(
                affiliationKey(aff.npe5__Contact__c, aff.npe5__Organization__c),
                aff
            );
        }

        List<npe5__Affiliation__c> affiliationsToUpsert =
            new List<npe5__Affiliation__c>();

        for (Id contactId : contactIds) {
            Id organizationId = employerByContactId.get(contactId);

            if (organizationId == null) {
                continue;
            }

            String key = affiliationKey(contactId, organizationId);
            npe5__Affiliation__c existing = existingByContactAndOrg.get(key);

            // Already the primary affiliation for this contact.
            if (existing != null && existing.npe5__Primary__c == true) {
                continue;
            }

            npe5__Affiliation__c affiliation = new npe5__Affiliation__c(
                npe5__Contact__c = contactId,
                npe5__Organization__c = organizationId,
                npe5__Status__c = 'Current',
                npe5__Primary__c = true,
                npe5__EndDate__c = null
            );

            if (existing != null) {
                affiliation.Id = existing.Id;
            } else {
                affiliation.npe5__StartDate__c = System.today();
            }

            affiliationsToUpsert.add(affiliation);
        }

        if (!affiliationsToUpsert.isEmpty()) {
            upsert affiliationsToUpsert;
        }
    }

    private static String affiliationKey(Id contactId, Id organizationId) {
        return contactId + '::' + organizationId;
    }
}
