public class FamilyService {
    /**
     * Creates NPSP Parent relationships from children to parents.
     *
     * NPSP's reciprocal relationship trigger creates the reciprocal record using
     * the configured Relationship Lookup (Son/Daughter/Child) for `Parent`.
     */
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // Copy to a filtered, local map so SOQL bind variables and skip logic
        // only handle valid Contact Id pairs.
        Map<Id, Id> pairs = new Map<Id, Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId != null && parentId != null) {
                pairs.put(childId, parentId);
            }
        }

        if (pairs.isEmpty()) {
            return;
        }

        Set<Id> childIds = pairs.keySet();
        Set<Id> parentIds = new Set<Id>(pairs.values());
        Set<Id> skippedChildIds = new Set<Id>();

        // One SOQL query to detect any existing relationship between the two
        // contacts in either direction.
        for (npe4__Relationship__c existing : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE (npe4__Contact__c IN :childIds AND npe4__RelatedContact__c IN :parentIds)
               OR (npe4__Contact__c IN :parentIds AND npe4__RelatedContact__c IN :childIds)
        ]) {
            // Existing child -> parent relationship
            if (pairs.containsKey(existing.npe4__Contact__c) &&
                pairs.get(existing.npe4__Contact__c) == existing.npe4__RelatedContact__c) {
                skippedChildIds.add(existing.npe4__Contact__c);
            }

            // Existing parent -> child relationship
            if (pairs.containsKey(existing.npe4__RelatedContact__c) &&
                pairs.get(existing.npe4__RelatedContact__c) == existing.npe4__Contact__c) {
                skippedChildIds.add(existing.npe4__RelatedContact__c);
            }
        }

        List<npe4__Relationship__c> relationshipsToInsert = new List<npe4__Relationship__c>();

        for (Id childId : pairs.keySet()) {
            if (skippedChildIds.contains(childId)) {
                continue;
            }

            relationshipsToInsert.add(new npe4__Relationship__c(
                npe4__Contact__c = childId,
                npe4__RelatedContact__c = pairs.get(childId),
                npe4__Type__c = 'Parent',
                npe4__Status__c = 'Current'
            ));
        }

        // One DML statement. NPSP's relationship trigger creates the reciprocal
        // record in the opposite direction using the Parent lookup settings.
        if (!relationshipsToInsert.isEmpty()) {
            insert relationshipsToInsert;
        }
    }
}
