global class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    private static final String STAGE_CLOSED_WON = 'Closed Won';
    private static final Decimal MAJOR_GIFT_MINIMUM_AMOUNT = 5000;
    private static final String TASK_SUBJECT = 'Major gift thank-you call';
    private static final String TASK_PRIORITY = 'High';
    private static final String TASK_STATUS = 'Not Started';
    private static final Integer FOLLOW_UP_DAYS = 3;

    global override npsp.TDTM_Runnable.DmlWrapper run(List<SObject> newlist, List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction, Schema.DescribeSObjectResult objResult) {

        npsp.TDTM_Runnable.DmlWrapper wrapper = new npsp.TDTM_Runnable.DmlWrapper();

        if (newlist == null || newlist.isEmpty() ||
            (triggerAction != npsp.TDTM_Runnable.Action.AfterInsert &&
             triggerAction != npsp.TDTM_Runnable.Action.AfterUpdate)) {
            return wrapper;
        }

        List<Opportunity> qualifyingOpportunities = new List<Opportunity>();

        if (triggerAction == npsp.TDTM_Runnable.Action.AfterInsert) {
            for (SObject so : newlist) {
                Opportunity opp = (Opportunity) so;
                if (isMajorGift(opp)) {
                    qualifyingOpportunities.add(opp);
                }
            }
        } else {
            if (oldlist == null) {
                return wrapper;
            }

            for (Integer i = 0; i < newlist.size(); i++) {
                Opportunity newOpp = (Opportunity) newlist[i];
                Opportunity oldOpp = (Opportunity) oldlist[i];

                if (isMajorGift(newOpp) && !isMajorGift(oldOpp)) {
                    qualifyingOpportunities.add(newOpp);
                }
            }
        }

        if (qualifyingOpportunities.isEmpty()) {
            return wrapper;
        }

        Set<Id> opportunityIds = new Set<Id>();
        for (Opportunity opp : qualifyingOpportunities) {
            opportunityIds.add(opp.Id);
        }

        Set<Id> opportunitiesWithExistingTask = new Set<Id>();
        for (Task existingTask : [
            SELECT WhatId
            FROM Task
            WHERE WhatId IN :opportunityIds AND Subject = :TASK_SUBJECT
        ]) {
            if (existingTask.WhatId != null) {
                opportunitiesWithExistingTask.add(existingTask.WhatId);
            }
        }

        for (Opportunity opp : qualifyingOpportunities) {
            if (opportunitiesWithExistingTask.contains(opp.Id)) {
                continue;
            }

            Task followUpTask = new Task();
            followUpTask.Subject = TASK_SUBJECT;
            followUpTask.Priority = TASK_PRIORITY;
            followUpTask.Status = TASK_STATUS;
            followUpTask.WhatId = opp.Id;
            followUpTask.WhoId = opp.npsp__Primary_Contact__c;
            followUpTask.OwnerId = opp.OwnerId;
            followUpTask.ActivityDate = opp.CloseDate == null ? null : opp.CloseDate.addDays(FOLLOW_UP_DAYS);

            wrapper.objectsToInsert.add(followUpTask);
        }

        return wrapper;
    }

    private Boolean isMajorGift(Opportunity opp) {
        return opp != null &&
               STAGE_CLOSED_WON.equals(opp.StageName) &&
               opp.Amount != null &&
               opp.Amount >= MAJOR_GIFT_MINIMUM_AMOUNT;
    }
}
