public with sharing class RecordAccessService {
    private static final Integer USER_RECORD_ACCESS_CHUNK_SIZE = 200;

    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> editable = new Set<Id>();

        if (recordIds == null || recordIds.isEmpty()) {
            return editable;
        }

        List<Id> ids = new List<Id>();
        for (Id recordId : recordIds) {
            if (recordId != null) {
                ids.add(recordId);
            }
        }

        if (ids.isEmpty()) {
            return editable;
        }

        for (Integer start = 0; start < ids.size(); start += USER_RECORD_ACCESS_CHUNK_SIZE) {
            Integer end = Math.min(start + USER_RECORD_ACCESS_CHUNK_SIZE, ids.size());

            List<Id> chunk = new List<Id>();
            for (Integer i = start; i < end; i++) {
                chunk.add(ids[i]);
            }

            for (UserRecordAccess access : [
                SELECT RecordId, HasEditAccess
                FROM UserRecordAccess
                WHERE UserId = :UserInfo.getUserId()
                AND RecordId IN :chunk
            ]) {
                if (access.HasEditAccess) {
                    editable.add(access.RecordId);
                }
            }
        }

        return editable;
    }
}
