public inherited sharing class TA_Account_CreateOnboardingTask implements TriggerAction.AfterInsert {

    private static final Set<String> QUALIFYING_ACCOUNT_TYPES = new Set<String>{
        'Customer - Direct',
        'Customer - Channel'
    };

    public void afterInsert(List<SObject> triggerNew) {
        List<Task> tasks = new List<Task>();
        Date onboardingActivityDate = Date.today().addDays(7);

        for (SObject record : triggerNew) {
            Account newAccount = (Account) record;

            if (String.isNotBlank(newAccount.Type) && QUALIFYING_ACCOUNT_TYPES.contains(newAccount.Type)) {
                tasks.add(new Task(
                    Subject = 'Onboard new customer',
                    WhatId = newAccount.Id,
                    OwnerId = newAccount.OwnerId,
                    ActivityDate = onboardingActivityDate,
                    Status = 'Not Started',
                    Priority = 'Normal'
                ));
            }
        }

        if (!tasks.isEmpty()) {
            insert tasks;
        }
    }
}
