public inherited sharing class TA_Contact_PreventDuplicateEmail implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    private static final String ERROR_MESSAGE = 'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        List<Contact> contacts = (List<Contact>) triggerNew;
        validateInsert(contacts);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        List<Contact> newContacts = (List<Contact>) triggerNew;
        Map<Id, Contact> oldContacts = new Map<Id, Contact>((List<Contact>) triggerOld);
        validateUpdate(newContacts, oldContacts);
    }

    private void validateInsert(List<Contact> contacts) {
        List<Contact> candidates = new List<Contact>();
        for (Contact c : contacts) {
            if (isEvaluable(c)) {
                candidates.add(c);
            }
        }

        if (candidates.isEmpty()) {
            return;
        }

        Set<Id> accountIds = collectAccountIds(candidates);
        List<Contact> existingContacts = queryExistingContacts(accountIds, new Set<Id>());
        Map<String, List<Id>> existingByKey = buildExistingByKey(existingContacts);
        Map<String, Id> firstByKey = new Map<String, Id>();

        for (Contact c : candidates) {
            String key = buildKey(c.AccountId, c.Email);
            if (existingByKey.containsKey(key)) {
                c.addError(ERROR_MESSAGE);
                continue;
            }
            if (firstByKey.containsKey(key)) {
                c.addError(ERROR_MESSAGE);
                continue;
            }
            firstByKey.put(key, c.Id);
        }
    }

    private void validateUpdate(List<Contact> newContacts, Map<Id, Contact> oldContacts) {
        List<Contact> candidates = new List<Contact>();
        for (Contact c : newContacts) {
            if (isEvaluable(c) && hasRelevantChange(c, oldContacts.get(c.Id))) {
                candidates.add(c);
            }
        }

        if (candidates.isEmpty()) {
            return;
        }

        Set<Id> accountIds = collectAccountIds(candidates);
        Set<Id> candidateIds = new Set<Id>();
        for (Contact c : candidates) {
            candidateIds.add(c.Id);
        }

        List<Contact> existingContacts = queryExistingContacts(accountIds, candidateIds);
        Map<String, List<Id>> existingByKey = buildExistingByKey(existingContacts);
        Map<String, Id> firstByKey = new Map<String, Id>();

        for (Contact c : candidates) {
            String key = buildKey(c.AccountId, c.Email);
            if (existingByKey.containsKey(key)) {
                c.addError(ERROR_MESSAGE);
                continue;
            }
            if (firstByKey.containsKey(key)) {
                c.addError(ERROR_MESSAGE);
                continue;
            }
            firstByKey.put(key, c.Id);
        }
    }

    private Boolean isEvaluable(Contact c) {
        return c.AccountId != null && String.isNotBlank(c.Email);
    }

    private Boolean hasRelevantChange(Contact newContact, Contact oldContact) {
        if (oldContact == null) {
            return true;
        }
        return newContact.Email != oldContact.Email || newContact.AccountId != oldContact.AccountId;
    }

    private Set<Id> collectAccountIds(List<Contact> contacts) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : contacts) {
            accountIds.add(c.AccountId);
        }
        return accountIds;
    }

    private List<Contact> queryExistingContacts(Set<Id> accountIds, Set<Id> excludedIds) {
        if (excludedIds.isEmpty()) {
            return [
                SELECT Id, AccountId, Email
                FROM Contact
                WHERE AccountId IN :accountIds
                  AND Email != null
            ];
        }

        return [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds
              AND Email != null
              AND Id NOT IN :excludedIds
        ];
    }

    private Map<String, List<Id>> buildExistingByKey(List<Contact> existingContacts) {
        Map<String, List<Id>> existingByKey = new Map<String, List<Id>>();
        for (Contact c : existingContacts) {
            if (!isEvaluable(c)) {
                continue;
            }
            String key = buildKey(c.AccountId, c.Email);
            List<Id> ids = existingByKey.get(key);
            if (ids == null) {
                ids = new List<Id>();
                existingByKey.put(key, ids);
            }
            ids.add(c.Id);
        }
        return existingByKey;
    }

    private String buildKey(Id accountId, String email) {
        return String.valueOf(accountId).toLowerCase() + '::' + email.trim().toLowerCase();
    }
}
