public inherited sharing class TA_Case_RollupOpenCount
        implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate,
                   TriggerAction.AfterDelete, TriggerAction.AfterUndelete {

    public void afterInsert(List<SObject> triggerNew) {
        recalculate(collectAccountIds(triggerNew));
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Set<Id> accountIds = new Set<Id>();

        for (Integer i = 0; i < triggerNew.size(); i++) {
            Case newCase = (Case) triggerNew[i];
            Case oldCase = (Case) triggerOld[i];

            if (newCase.IsClosed == oldCase.IsClosed && newCase.AccountId == oldCase.AccountId) {
                continue;
            }

            if (!oldCase.IsClosed && oldCase.AccountId != null) {
                accountIds.add(oldCase.AccountId);
            }

            if (!newCase.IsClosed && newCase.AccountId != null) {
                accountIds.add(newCase.AccountId);
            }
        }

        recalculate(accountIds);
    }

    public void afterDelete(List<SObject> triggerOld) {
        recalculate(collectOpenCaseAccountIds(triggerOld));
    }

    public void afterUndelete(List<SObject> triggerNew) {
        recalculate(collectOpenCaseAccountIds(triggerNew));
    }

    private static Set<Id> collectAccountIds(List<SObject> records) {
        Set<Id> accountIds = new Set<Id>();

        if (records == null) {
            return accountIds;
        }

        for (SObject record : records) {
            Case caseRecord = (Case) record;
            if (caseRecord.AccountId != null) {
                accountIds.add(caseRecord.AccountId);
            }
        }

        return accountIds;
    }

    private static Set<Id> collectOpenCaseAccountIds(List<SObject> records) {
        Set<Id> accountIds = new Set<Id>();

        if (records == null) {
            return accountIds;
        }

        for (SObject record : records) {
            Case caseRecord = (Case) record;
            if (!caseRecord.IsClosed && caseRecord.AccountId != null) {
                accountIds.add(caseRecord.AccountId);
            }
        }

        return accountIds;
    }

    private static void recalculate(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        Map<Id, Integer> openCaseCountByAccountId = new Map<Id, Integer>();
        for (Id accountId : accountIds) {
            openCaseCountByAccountId.put(accountId, 0);
        }

        for (AggregateResult result : [
            SELECT AccountId, COUNT(Id) openCount
            FROM Case
            WHERE AccountId IN :accountIds AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accountId = (Id) result.get('AccountId');
            Integer openCount = (Integer) result.get('openCount');
            openCaseCountByAccountId.put(accountId, openCount);
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : openCaseCountByAccountId.keySet()) {
            Account accountToUpdate = new Account();
            accountToUpdate.Id = accountId;
            accountToUpdate.FB_Open_Case_Count__c = openCaseCountByAccountId.get(accountId);
            accountsToUpdate.add(accountToUpdate);
        }

        update accountsToUpdate;
    }
}
